const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',car:'M3 14l2-7h14l2 7v5h-3v-2H6v2H3z M3 13h18 M7 16h.01 M17 16h.01',orders:'M7 3h10v3H7z M6 5H4v16h16V5h-2 M8 11h8 M8 15h5',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-3.87',wallet:'M3 6h17v15H3z M3 6V3h14v3 M16 11h5v5h-5z',chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 3 3-1 3 3-1 3 2 1v3l-3 1 1 3-3 3-3-1-1 2h-3l-1-3-3 1-3-3 1-3-2-1v-3l3-1-1-3 3-3 3 1z',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',plus:'M12 5v14 M5 12h14',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z M12 13a3 3 0 1 0 0-6 3 3 0 0 0 0 6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v6l4 2',logout:'M9 3H3v18h6 M9 12h13 M17 7l5 5-5 5',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',check:'M5 12l4 4L20 5',phone:'M5 3l4 1 1 5-3 2c2 4 3 5 6 6l2-3 5 1 1 4c-1 5-9 1-13-3S0 5 5 3z',menu:'M3 6h18 M3 12h18 M3 18h18',user:'M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10 M3 22v-2a7 7 0 0 1 7-7h4a7 7 0 0 1 7 7v2',star:'M12 2l3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z',home:'M3 10l9-8 9 8v12h-7v-8h-4v8H3z',edit:'M15 5l4 4 M3 21l5-1L21 7l-5-5L3 15z',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 10v7 M12 6v1',bag:'M5 8h14l-1 13H6z M9 8V6a3 3 0 0 1 6 0v2',cart:'M3 4h2l2 11h11l2-8H6 M9 20h.01 M17 20h.01',minus:'M5 12h14',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const initials=s=>String(s).split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();
const place=id=>places.find(p=>p.id===id)?.name||id;
const date=t=>{const d=new Date(t);return d.getDate()+' '+['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentabr','oktabr','noyabr','dekabr'][d.getMonth()];};
const time=t=>new Date(t).toLocaleTimeString('uz-UZ',{hour:'2-digit',minute:'2-digit'});
let state,fullDemo,user,page='overview',filter='all',search='',from='amir',to='city',tariff='economy',loginTab='login',busy=false,menu=false;
let shopCat='all',shopQuery='',shopTab='orders';
const store={get(k,d){try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}}};
let cart=store.get('navo-cart',{});if(typeof cart!=='object'||Array.isArray(cart))cart={};
const saveCart=()=>store.set('navo-cart',cart);
let mode=sessionStorage.getItem('navo-mode')||'',token=sessionStorage.getItem('navo-token')||'',apiBase=localStorage.getItem('navo-server')||'';
const demoUsers={admin:{id:'demo-admin',name:'Administrator',phone:'+998900000000',role:'admin'},rider:{id:'demo-rider',name:'Akobir',phone:'+998900000010',role:'rider'},driver:{id:'demo-driver',name:'Aziz Karimov',phone:'+998901110101',role:'driver',driverId:'d1'}};
function loadDemo(){try{fullDemo=JSON.parse(localStorage.getItem('navo-demo-v1'));}catch{}if(!fullDemo?.settings){fullDemo=seed();localStorage.setItem('navo-demo-v1',JSON.stringify(fullDemo));}if(!fullDemo.shop){fullDemo.shop=seed().shop;localStorage.setItem('navo-demo-v1',JSON.stringify(fullDemo));}state=visibleState(fullDemo,user);}
async function api(route,data){if(!apiBase&&location.hostname==='appassets.androidplatform.net')throw Error('APKga server hali ulanmagan. Bu oynani yoping va Yo‘lovchi, Haydovchi yoki Admin paneli orqali sinov rejimiga kiring.');const res=await fetch(apiBase+'/api/'+route,{method:data?'POST':'GET',headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(12000)});let v;try{v=await res.json();}catch{throw Error('Bu manzilda taksopark serveri topilmadi. Namuna manzili ishlamaydi; haqiqiy HTTPS server manzili kerak.');}if(!res.ok)throw Error(v.error||'Serverga ulanishda xato.');return v;}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),4000);}
function setDemo(role){mode='demo';user=demoUsers[role];page=role==='admin'?'overview':'home';sessionStorage.setItem('navo-mode','demo');sessionStorage.setItem('navo-role',role);loadDemo();filter='all';search='';render();}
async function act(action,payload,msg='Saqlandi'){if(busy)return;busy=true;try{if(mode==='demo'){loadDemo();fullDemo=applyAction(fullDemo,user,action,payload);localStorage.setItem('navo-demo-v1',JSON.stringify(fullDemo));state=visibleState(fullDemo,user);}else{const r=await api('action',{action,payload});state=r.state;}render();toast(msg);return true;}catch(e){toast(e.message);return false;}finally{busy=false;}}
function logo(){return `<div><div class="logo"><img src="icon.svg" alt=""><span class="brand-name">${esc(state?.settings.name||'NAVO TAXI')}</span></div></div>`;}
function modes(){return mode==='demo'?`<div class="mode-switch" aria-label="Sinov roli">${[['rider','Yo‘lovchi'],['driver','Haydovchi'],['admin','Admin']].map(([r,n])=>`<button data-role="${r}" class="${user.role===r?'active':''}">${n}</button>`).join('')}</div>`:`<span class="pill green"><span class="dot"></span> Server ulangan</span>`;}
function badge(s){return `<span class="pill ${s==='completed'?'green':s==='cancelled'?'red':s==='pending'?'orange':'blue'}"><span class="dot"></span>${labels[s]||esc(s)}</span>`;}
function mapSvg(route=false){
 const a=places.find(p=>p.id===from),b=places.find(p=>p.id===to);
 const blocks=Array.from({length:12},(_,r)=>Array.from({length:15},(_,c)=>{const x=c*65-20+(r%2)*10,y=r*48-10;const green=(r*7+c*3)%17===0;return `<rect x="${x}" y="${y}" width="${43+(c%3)*3}" height="${29+(r%2)*5}" rx="${green?8:3}" fill="${green?'#d6e3c5':(c+r)%3===0?'#e2e7db':'#e7ebdf'}"/>`}).join('')).join('');
 const cars=(state.drivers.length?state.drivers:[{id:'none'}]).filter(d=>d.online).map((d,i)=>`<g transform="translate(${[390,650,255,735][i%4]},${[200,330,350,175][i%4]}) rotate(${[-25,45,-15,65][i%4]})"><rect x="-10" y="-19" width="20" height="38" rx="7" fill="#fff" stroke="#7f9471" stroke-width="1.5"/><rect x="-7" y="-10" width="14" height="13" rx="3" fill="#465b40"/><path d="M-6 9h12" stroke="#a9c582" stroke-width="4"/></g>`).join('');
 return `<svg class="map-art" viewBox="0 0 940 560" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Toshkentning sxematik demo xaritasi"><rect width="940" height="560" fill="#f1f3eb"/>${blocks}<path d="M-20 420C170 380 270 350 330 160S500 100 620-30" fill="none" stroke="#c9dfe0" stroke-width="19"/><g fill="none" stroke="#fffdf5" stroke-width="16"><path d="M-20 330L280 315 590 230 970 200"/><path d="M180-30L260 220 460 570"/><path d="M610-20L560 170 640 580"/><path d="M0 90L340 135 930 80"/><path d="M-10 460L310 470 940 390"/><path d="M820-20L730 210 800 580"/></g><g fill="none" stroke="#e4dfc8" stroke-width="1.5"><path d="M-20 330L280 315 590 230 970 200"/><path d="M180-30L260 220 460 570"/><path d="M610-20L560 170 640 580"/></g><g font-family="Segoe UI,Arial" font-size="11" fill="#a0aa94" letter-spacing="2"><text x="350" y="125">YUNUSOBOD</text><text x="155" y="240">SHAYXONTOHUR</text><text x="690" y="115">MIRZO ULUG‘BEK</text><text x="180" y="515">CHILONZOR</text><text x="665" y="480">MIROBOD</text></g><g font-family="Segoe UI,Arial" font-size="11" fill="#8b967e">${places.slice(0,7).map(p=>`<text x="${p.x*9.4+13}" y="${p.y*5.6+4}">${esc(p.name.replace('Toshkent ','').replace('Amir Temur xiyoboni','Amir Temur'))}</text><circle cx="${p.x*9.4}" cy="${p.y*5.6}" r="3" fill="#aab69c"/>`).join('')}</g>${route&&a&&b?`<path d="M${a.x*9.4} ${a.y*5.6}L${a.x*9.4} ${(a.y*5.6+b.y*5.6)/2}L${b.x*9.4} ${(a.y*5.6+b.y*5.6)/2}L${b.x*9.4} ${b.y*5.6}" fill="none" stroke="#8da960" stroke-width="18" opacity=".17"/><path d="M${a.x*9.4} ${a.y*5.6}L${a.x*9.4} ${(a.y*5.6+b.y*5.6)/2}L${b.x*9.4} ${(a.y*5.6+b.y*5.6)/2}L${b.x*9.4} ${b.y*5.6}" fill="none" stroke="#536e37" stroke-width="5" stroke-linejoin="round"/><circle cx="${a.x*9.4}" cy="${a.y*5.6}" r="13" fill="#d5eb84" stroke="white" stroke-width="4"/><circle cx="${b.x*9.4}" cy="${b.y*5.6}" r="13" fill="#203725" stroke="white" stroke-width="4"/>`:''}${cars}</svg>`;
}
function map(route=false,cls='admin-map'){return `<div class="map ${cls}">${mapSvg(route)}<span class="map-tag">${esc(state.settings.city)} <span style="color:#a7b29a">/</span> Demo xarita</span><span class="map-credit">Sxematik tasvir · GPS ulanmagan</span>${cls==='consumer-map'?`<div class="map-bottom">${icon('shield')}<div><p>Yo‘lingiz doimo xotirjam bo‘lsin</p><small>Manzilni tanlang. Qolganini bizga ishoning.</small></div></div>`:''}</div>`;}
function car(color='#e5e9e2'){return `<svg class="car-art" viewBox="0 0 100 45" aria-hidden="true"><ellipse cx="50" cy="37" rx="42" ry="4" fill="#000" opacity=".07"/><path d="M8 29l5-12 17-3 12-9h25l15 15 10 4 3 10H7z" fill="${color}" stroke="#9ca69a" stroke-width=".8"/><path d="M34 15l10-8h20l9 11-40-1z" fill="#53675e"/><path d="M52 7v11" stroke="#a6b3a8" stroke-width="2"/><rect x="13" y="22" width="10" height="4" rx="1" fill="#fffde4"/><rect x="86" y="25" width="7" height="3" rx="1" fill="#c87560"/><circle cx="26" cy="33" r="7" fill="#29392f"/><circle cx="26" cy="33" r="3" fill="#b7c2b6"/><circle cx="78" cy="33" r="7" fill="#29392f"/><circle cx="78" cy="33" r="3" fill="#b7c2b6"/><path d="M49 22h6" stroke="#7a8979" stroke-width="2"/></svg>`;}
function stats(){const completed=state.orders.filter(o=>o.status==='completed'),sum=completed.reduce((a,o)=>a+o.price,0),online=state.drivers.filter(d=>d.online&&!d.blocked).length;return `<div class="stats">${[
 ['Jami buyurtmalar',state.orders.length,'','Barcha saqlangan buyurtmalar','orders'],['Onlayn haydovchilar',online,`/ ${state.drivers.length}`,'Parkdagi haydovchilar','car'],['Safarlar tushumi',money(sum),"so‘m",`${completed.length} ta yakunlangan safar`,'wallet'],['Faol buyurtmalar',state.orders.filter(o=>active(o.status)).length,'','Yangi va bajarilayotgan safarlar','chart']
 ].map(([n,v,unit,foot,ic],i)=>`<div class="stat ${i===0?'featured':''}"><div class="row between"><span class="stat-label">${n}</span><div class="stat-icon">${icon(ic)}</div></div><div class="stat-value">${v} <span>${unit}</span></div><div class="stat-foot">${foot}</div></div>`).join('')}</div>`;}
function chart(){const now=new Date();now.setHours(0,0,0,0);const days=Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(d.getDate()-6+i);const n=state.orders.filter(o=>o.status==='completed'&&o.completedAt>=d.getTime()&&o.completedAt<d.getTime()+86400000).reduce((a,o)=>a+o.price,0);return {n,d};});const max=Math.max(1,...days.map(d=>d.n));return `<div class="card"><div class="card-head"><div><h2>Safarlar tushumi</h2><small>Oxirgi 7 kun</small></div><span class="pill">UZS</span></div><div class="chart-total">${money(days.reduce((a,d)=>a+d.n,0))} <span>so‘m</span></div><div class="chart">${days.map(({d,n},i)=>`<div class="chart-col" title="${date(d)}: ${money(n)} so‘m"><div class="bar ${i===6?'today':''}" style="height:${Math.max(2,n/max*90)}%"></div><small>${['Ya','Du','Se','Ch','Pa','Ju','Sh'][d.getDay()]}</small></div>`).join('')}</div><div class="chart-note"><span class="dot" style="background:#a9c86a"></span> Yakunlangan safarlardan hisoblangan</div></div>`;}
const navs=[['overview','grid','Bosh sahifa'],['orders','orders','Buyurtmalar'],['shop','bag','Do‘kon'],['drivers','users','Haydovchilar'],['finance','wallet','Moliya'],['settings','settings','Sozlamalar']];
function adminShell(content){return `<div class="menu-scrim ${menu?'open':''}" data-action="menu"></div><aside class="sidebar ${menu?'open':''}">${logo()}<div class="brand-desc">PARK BOSHQARUVI</div><div class="tag">ASOSIY MENYU</div><nav>${navs.map(([p,i,n])=>`<button class="nav-item ${page===p?'active':''}" data-page="${p}">${icon(i)}<span>${n}</span>${p==='orders'?`<span class="nav-count">${state.orders.filter(o=>active(o.status)).length}</span>`:p==='shop'?`<span class="nav-count">${state.shop.orders.filter(o=>shopActive(o.status)).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="park-card"><div class="row">${icon('shield')}<strong style="font-size:12px">Barchasi nazoratingizda</strong></div><p>Parkingiz. Qoidalaringiz.<br>Yagona boshqaruv markazi.</p><button class="text-link" data-page="settings" style="color:#d4ed69">Parkni sozlash ${icon('arrow')}</button></div><div class="row sidebar-user"><div class="avatar dark">AD</div><div class="user-name" style="font-size:12px">Administrator<small>Park boshqaruvchisi</small></div><button title="Chiqish" data-action="logout">${icon('logout')}</button></div></div></aside><main class="admin-shell"><header class="topbar"><button class="round mobile-menu" data-action="menu" aria-label="Menyu">${icon('menu')}</button><div class="breadcrumb">Ish maydoni ${icon('chevron')} <b>${navs.find(n=>n[0]===page)?.[2]||'Bosh sahifa'}</b></div><div class="top-actions">${modes()}<button class="round" data-action="activity" aria-label="Faollik jurnali">${icon('bell')}</button><div class="avatar">AD</div></div></header>${mode==='demo'?'<div class="demo-strip">SINOV REJIMI · Namunaviy ma’lumotlar · Ushbu brauzer yoki qurilmada saqlanadi</div>':''}<div class="admin-content">${content}</div></main>`;}
function heading(title,sub,button=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(state.settings.name)} / BOSHQARUV MARKAZI</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`;}
function orderRows(orders){return orders.length?orders.map(o=>{const d=state.drivers.find(d=>d.id===o.driverId);return `<tr><td><b>#${esc(o.id)}</b><small>${date(o.createdAt)}, ${time(o.createdAt)}</small></td><td><div class="row"><span class="avatar">${esc(initials(o.rider))}</span><div>${esc(o.rider)}<small>${esc(o.phone)}</small></div></div></td><td><div class="route-text">${esc(place(o.from))}<small>↳ ${esc(place(o.to))}</small></div></td><td>${d?esc(d.name):'<span class="muted">Kutilmoqda</span>'}<small>${d?esc(d.car):'Haydovchi biriktirilmagan'}</small></td><td><b>${money(o.price)}</b><small>so‘m · naqd</small></td><td>${badge(o.status)}</td><td><button class="round" style="width:28px;height:28px" data-action="order-detail" data-id="${esc(o.id)}" aria-label="Buyurtmani ochish">${icon('chevron')}</button></td></tr>`}).join(''):`<tr><td colspan="7" class="empty">Buyurtmalar topilmadi.</td></tr>`;}
function orderTable(orders){return `<div class="table-wrap"><table class="table"><thead><tr><th>Buyurtma</th><th>Yo‘lovchi</th><th>Yo‘nalish</th><th>Haydovchi</th><th>Narx</th><th>Holat</th><th></th></tr></thead><tbody>${orderRows(orders)}</tbody></table></div>`;}
function overview(){return heading('Parkingiz bir qarashda',`${date(Date.now())} · Xush kelibsiz, bugungi ishni birga boshlaymiz.`,`<button class="btn primary" data-action="new-order">${icon('plus')} Yangi buyurtma</button>`)+stats()+`<div class="dashboard-grid"><div class="card"><div class="card-head"><div><h2>Park xaritasi</h2><small>Shahar bo‘ylab faoliyat ko‘rinishi</small></div><span class="live"><span class="dot"></span> Sxematik</span></div>${map()}<div class="map-legend"><span><i class="dot" style="color:#91a66c"></i> Onlayn: ${state.drivers.filter(d=>d.online).length}</span><span><i class="dot" style="color:#d7b36b"></i> Safarda: ${state.orders.filter(o=>o.status==='riding').length}</span><span><i class="dot" style="color:#bac2b4"></i> GPS ulanmagan</span></div></div>${chart()}</div><div class="card space"><div class="card-head"><div class="row"><h2>Oxirgi buyurtmalar</h2><span class="pill">${state.orders.length}</span></div><button class="text-link" data-page="orders">Barchasini ko‘rish ${icon('arrow')}</button></div>${orderTable(state.orders.slice(0,5))}<div class="table-footer"><span>Oxirgi ${Math.min(5,state.orders.length)} ta buyurtma</span><span>${mode==='demo'?'Sinov ma’lumotlari':'Serverdan yangilangan'}</span></div></div>`;}
function ordersPage(){const orders=state.orders.filter(o=>(filter==='all'||(filter==='active'?active(o.status):o.status===filter))&&`${o.id} ${o.rider} ${o.phone} ${place(o.from)} ${place(o.to)}`.toLowerCase().includes(search.toLowerCase()));return heading('Buyurtmalar','Har bir safar — sizning nazoratingizda.',`<button class="btn primary" data-action="new-order">${icon('plus')} Yangi buyurtma</button>`)+`<div class="card"><div class="card-head"><h2>Buyurtmalar ro‘yxati</h2><button class="btn outline small" data-action="export">${icon('download')} CSV</button></div><div class="toolbar"><div class="filters">${[['all','Barchasi'],['active','Faol'],['pending','Yangi'],['completed','Yakunlangan'],['cancelled','Bekor qilingan']].map(([f,n])=>`<button data-filter="${f}" class="${filter===f?'active':''}">${n}</button>`).join('')}</div><label class="search">${icon('search')}<input data-search placeholder="Ism, telefon yoki buyurtma..." value="${esc(search)}" aria-label="Buyurtmalarni qidirish"></label></div>${orderTable(orders)}<div class="table-footer">${orders.length} ta buyurtma topildi</div></div>`;}
function driversPage(){return heading('Haydovchilar','Jamoangiz va avtomobillar — bitta joyda.',`<button class="btn primary" data-action="driver-edit">${icon('plus')} Haydovchi qo‘shish</button>`)+`<div class="driver-grid">${state.drivers.map(d=>{const count=state.orders.filter(o=>o.driverId===d.id&&o.status==='completed').length;const b=state.orders.some(o=>o.driverId===d.id&&active(o.status));return `<div class="card driver-card"><div class="row between"><div class="avatar">${esc(initials(d.name))}</div><span class="pill ${d.blocked?'red':b?'blue':d.online?'green':''}"><span class="dot"></span>${d.blocked?'Bloklangan':b?'Safarda':d.online?'Onlayn':'Oflayn'}</span></div><h3>${esc(d.name)}</h3><p>${esc(d.car)} · ${esc(d.plate)}</p><div class="driver-details"><div><b>${count}</b><small>Yakunlangan safar</small></div><div style="margin-left:auto"><b>${d.rating?d.rating.toFixed(1):'—'} <span style="font-size:13px;color:#b0bf67">★</span></b><small>${mode==='demo'?'Demo reyting':'Reyting yo‘q'}</small></div></div><div class="row between"><a href="tel:${esc(d.phone)}" class="text-link">${icon('phone')} ${esc(d.phone)}</a><button class="round" data-action="driver-edit" data-id="${esc(d.id)}" aria-label="Haydovchini tahrirlash">${icon('edit')}</button></div></div>`}).join('')||'<div class="card empty">Hozircha haydovchi yo‘q. Birinchi haydovchini qo‘shing.</div>'}</div>`;}
function financePage(){const completed=state.orders.filter(o=>o.status==='completed');const gross=completed.reduce((s,o)=>s+o.price,0),commission=completed.reduce((s,o)=>s+o.price*o.commission/100,0);return heading('Moliya va hisobotlar','Yakunlangan safarlar bo‘yicha hisob-kitob.',`<button class="btn outline" data-action="export">${icon('download')} Hisobotni yuklash</button>`)+`<div class="stats">${[['Jami tushum',gross],['Park komissiyasi',commission],['Haydovchilar ulushi',gross-commission],['O‘rtacha chek',completed.length?gross/completed.length:0]].map(([n,v],i)=>`<div class="stat ${i===1?'featured':''}"><span class="stat-label">${n}</span><div class="stat-value">${money(v)} <span>so‘m</span></div><div class="stat-foot">Barcha yakunlangan safarlar</div></div>`).join('')}</div><div class="income-grid">${chart()}<div class="card pad"><h2>Haydovchilar bo‘yicha</h2><div class="space">${state.drivers.map(d=>{const list=completed.filter(o=>o.driverId===d.id);return `<div class="audit"><div class="avatar">${esc(initials(d.name))}</div><div>${esc(d.name)}<small>${list.length} ta safar</small></div><strong style="margin-left:auto;font-size:12px">${money(list.reduce((s,o)=>s+o.price*(1-o.commission/100),0))} so‘m</strong></div>`}).join('')||'<p class="empty">Hali haydovchi yo‘q.</p>'}</div></div></div><div class="notice space">Hisobot safar summalaridan hisoblanadi. Naqd pul inkassatsiyasi va bank hisob-kitoblari bu versiyada tekshirilmaydi.</div>`;}
function settingsPage(){const s=state.settings;return heading('Park sozlamalari','Nom, aloqa ma’lumotlari va tariflarni shu yerdan boshqaring.')+`<div class="settings-grid"><section class="card pad"><h2>Asosiy ma’lumotlar</h2><form data-form="settings" class="space"><label class="field">Taksopark nomi<input name="name" value="${esc(s.name)}" maxlength="32" required></label><label class="field">Shahar<input name="city" value="${esc(s.city)}" maxlength="40" required><small>Shahar nomi brending uchun. Demo yo‘nalishlar hozircha Toshkentga tegishli.</small></label><label class="field">Aloqa telefoni<input name="phone" type="tel" value="${esc(s.phone)}" required></label><label class="field">Park komissiyasi (%)<input name="commission" type="number" min="0" max="40" step="0.1" value="${s.commission}" required><small>Yangi buyurtmalarga qo‘llanadi. Avvalgi safarlar o‘zgarmaydi.</small></label><button class="btn primary full">${icon('check')} O‘zgarishlarni saqlash</button></form></section><div class="column"><section class="card pad"><h2>Safar tariflari</h2>${state.tariffs.map(t=>`<form data-form="tariff" class="tariff-row"><input type="hidden" name="id" value="${t.id}"><div class="row between"><h3>${esc(t.name)}</h3><button class="btn outline small">Saqlash</button></div><div class="two"><label class="field">Boshlang‘ich (so‘m)<input name="base" type="number" min="0" max="1000000" value="${t.base}" required></label><label class="field">Har km (so‘m)<input name="perKm" type="number" min="1" max="100000" value="${t.perKm}" required></label></div></form>`).join('')}</section><section class="card pad"><div class="row between"><div><h3>Hisob xavfsizligi</h3><p class="hint">${mode==='demo'?'Demo rejimda parol ishlatilmaydi.':'Admin parolingizni yangilang.'}</p></div><button class="btn outline small" data-action="password">Parol</button></div></section></div></div><div class="notice space">Park nomi saqlangach, yo‘lovchi va haydovchi ekranlarida ham yangilanadi. ${mode==='demo'?'Sinov rejimidagi o‘zgarishlar shu qurilmada saqlanadi.':'Serverga ulangan qurilmalar o‘zgarishni keyingi yangilanishda oladi.'}</div>`;}
function consumerShell(content){const driver=user.role==='driver',tabs=driver?[['home','car','Ish oynasi'],['history','orders','Safarlar'],['profile','user','Profil']]:[['home','car','Taksi'],['shop','bag','Do‘kon'],['cart','cart','Savat'],['history','clock','Tarix'],['profile','user','Profil']];const count=cartCount();const nav=tabs.map(([p,i,n])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}${n}${p==='cart'&&count?`<span class="nav-badge">${count}</span>`:''}</button>`).join('');return `<header class="mobile-header">${logo()}<nav class="consumer-nav">${nav}</nav><div class="row">${modes()}<button class="round" data-action="support" aria-label="Yordam">${icon('phone')}</button></div></header>${mode==='demo'?'<div class="demo-strip">SINOV REJIMI · Haqiqiy taksi chaqirilmaydi va buyurtma yetkazilmaydi</div>':''}<main class="consumer-main">${content}</main><nav class="bottom-nav">${nav}</nav>`;}
function routeFields(){return `<div class="route-fields"><div class="route-field"><span class="point"></span><div><label for="from">Qayerdan</label><select id="from" name="from" data-route="from">${places.map(p=>`<option value="${p.id}" ${from===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="route-field destination"><span class="point"></span><div><label for="to">Qayerga</label><select id="to" name="to" data-route="to">${places.map(p=>`<option value="${p.id}" ${to===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div></div>`;}
function riderHome(){const current=state.orders.find(o=>active(o.status));let q;try{q=quote(state,from,to,tariff)}catch{}return `<div class="consumer-hero"><div><div class="eyebrow">HAR KUNI. HAR MANZILGA.</div><h1>Qayerga boramiz, ${esc(user.name.split(' ')[0])}?</h1><p>Qulay safar bir necha bosishdan boshlanadi.</p></div><span class="pill">${icon('pin')} ${esc(state.settings.city)}</span></div><div class="consumer-layout"><div><div class="card booking-panel">${current?activeRide(current):`<h2>Safaringizni rejalang</h2>${routeFields()}<div class="tariff-options">${state.tariffs.map((t,i)=>`<button class="tariff-option ${tariff===t.id?'selected':''}" data-tariff="${t.id}">${car(['#e5e9e2','#b3c2ac','#485747'][i])}<b>${esc(t.name)}</b><small>${q?money(quote(state,from,to,t.id).price):'—'} so‘m</small></button>`).join('')}</div><div class="trip-estimate"><div><small>Taxminiy narx</small><b>${q?money(q.price):'—'} <span style="font-size:12px;font-weight:400">so‘m</span></b></div><div style="text-align:right"><small>Taxminiy yo‘l</small><b style="font-size:17px">${q?q.km+' km · '+q.minutes+' daq':'Manzilni tekshiring'}</b></div></div><div class="payment"><span class="row">${icon('wallet')} Naqd pul</span><span class="pill green">Safar oxirida</span></div><button class="btn primary full" data-action="book" ${!q?'disabled':''}>Taksi chaqirish ${icon('arrow')}</button><p class="hint">Demo yo‘nalish va taxminiy masofa. GPS, yo‘l tirbandligi hamda aniq marshrut hali ulanmagan.</p>`}</div><div class="promo-card">${icon('shield')}<div><p>O‘zingizga qulay safarni tanlang</p><small>Ekonom, Komfort yoki Biznes — tanlov sizniki.</small></div></div></div>${map(true,'consumer-map')}</div>`;}
function activeRide(o){const d=state.drivers.find(d=>d.id===o.driverId);const step=['pending','accepted','arrived','riding'].indexOf(o.status);return `<div class="status-card"><span class="pill green">${esc(o.id)}</span><h3>${labels[o.status]}</h3><p class="hint">${o.status==='pending'?'Buyurtma haydovchi qabul qilishini kutmoqda.':o.status==='accepted'?'Haydovchi jo‘nash manzilingizga yo‘l oldi.':o.status==='arrived'?'Haydovchi sizni kutmoqda.':'Safaringiz davom etmoqda.'}</p><div class="status-steps">${[0,1,2,3].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="detail-list"><div>${esc(place(o.from))}<p class="hint">↓ ${esc(place(o.to))}</p></div><div class="row"><small>Safar narxi</small><b>${money(o.price)} so‘m</b></div></div>${d?`<div class="row space"><span class="avatar">${esc(initials(d.name))}</span><div><b style="font-size:13px">${esc(d.name)}</b><p class="hint" style="margin-top:4px">${esc(d.car)} · ${esc(d.plate)}</p></div></div><a href="tel:${esc(d.phone)}" class="btn outline full space">${icon('phone')} Haydovchiga qo‘ng‘iroq</a>`:''}</div>${['pending','accepted'].includes(o.status)?`<button class="btn danger full space" data-action="cancel" data-id="${o.id}">Buyurtmani bekor qilish</button>`:''}${mode==='demo'?'<div class="notice space">Jarayonni davom ettirish uchun yuqoridan Haydovchi roliga o‘ting va buyurtmani qabul qiling.</div>':''}`;}
function driverHome(){const d=state.drivers.find(d=>d.id===user.driverId);if(!d)return '<div class="empty">Haydovchi profili topilmadi.</div>';const current=state.orders.find(o=>o.driverId===d.id&&active(o.status));const completed=state.orders.filter(o=>o.driverId===d.id&&o.status==='completed');const net=completed.reduce((s,o)=>s+o.price*(1-o.commission/100),0);return `<div class="consumer-hero"><div><div class="eyebrow">HAYDOVCHI KABINETI</div><h1>Salom, ${esc(d.name.split(' ')[0])}!</h1><p>${esc(d.car)} · ${esc(d.plate)}</p></div><span class="pill green">${icon('star')} ${d.rating||'—'}</span></div><div class="driver-hero"><div><h2>${d.blocked?'Profil bloklangan':d.online?'Siz onlaynsiz':'Ishga tayyormisiz?'}</h2><p>${d.online?'Yangi buyurtmalarni qabul qilishingiz mumkin.':'Buyurtmalarni ko‘rish uchun onlayn holatga o‘ting.'}</p></div><button class="toggle ${d.online?'on':''}" data-action="online" role="switch" aria-checked="${d.online}" aria-label="Onlayn holati" ${d.blocked?'disabled':''}></button></div><div class="stats" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><span class="stat-label">Sizning daromadingiz</span><div class="stat-value">${money(net)} <span>so‘m</span></div><small class="stat-foot">Komissiyadan keyingi jami ulush</small></div><div class="stat featured"><span class="stat-label">Yakunlangan safarlar</span><div class="stat-value">${completed.length}</div><small class="stat-foot">Barcha vaqt davomida</small></div></div><div class="row between space" style="margin-bottom:18px"><h2>${current?'Joriy safar':'Yangi buyurtmalar'}</h2><span class="pill">${current?'1':state.orders.filter(o=>o.status==='pending').length} ta</span></div><div class="requests-grid">${current?requestCard(current,true):state.shop.orders.some(o=>o.courierId===d.id&&shopActive(o.status))?'<div class="card empty">Avval joriy yetkazib berishni yakunlang.</div>':d.online?state.orders.filter(o=>o.status==='pending').map(o=>requestCard(o,false)).join('')||'<div class="card empty">Yangi buyurtma kutilmoqda.</div>':'<div class="card empty">Onlayn bo‘lsangiz, buyurtmalar shu yerda ko‘rinadi.</div>'}</div>${deliverySection(d,current)}`;}
function requestCard(o,current){const next=({accepted:['arrived','Manzilga yetib keldim'],arrived:['riding','Safarni boshlash'],riding:['completed','Safarni yakunlash']})[o.status];return `<div class="card request-card"><div class="row between">${badge(o.status)}<small>${esc(o.id)}</small></div><div class="request-route"><span><i class="dot"></i>${esc(place(o.from))}</span><span><i class="dot" style="background:#354f2c"></i>${esc(place(o.to))}</span></div><div class="row between" style="margin-bottom:20px;font-size:11px;color:#859377"><span>${o.km} km · ~${o.minutes} daq</span><span>${esc(state.tariffs.find(t=>t.id===o.tariff)?.name)} · Naqd</span></div>${current?`<div class="row between" style="margin-bottom:20px"><span style="font-size:13px">${esc(o.rider)}</span><a href="tel:${esc(o.phone)}" class="text-link">${icon('phone')} Qo‘ng‘iroq</a></div>`:''}<div class="request-footer"><div><b>${money(o.price)}</b><small> so‘m</small></div>${current?`<button class="btn primary" data-action="advance" data-id="${o.id}" data-status="${next?.[0]}">${next?.[1]} ${icon('arrow')}</button>`:`<button class="btn lime" data-action="accept" data-id="${o.id}">Qabul qilish ${icon('arrow')}</button>`}</div></div>`;}
function historyPage(){const list=state.orders.filter(o=>user.role==='rider'?o.riderId===user.id:o.driverId===user.driverId);const sl=state.shop.orders.filter(o=>user.role==='rider'?o.customerId===user.id:o.courierId===user.driverId);return `<div class="consumer-hero"><div><div class="eyebrow">SIZNING TARIXINGIZ</div><h1>Buyurtmalar tarixi</h1><p>${list.length} ta safar · ${sl.length} ta do‘kon buyurtmasi</p></div></div>${sl.length?`<h2 class="section-title">Do‘kon buyurtmalari</h2>${sl.map(o=>`<button class="card history-card full" data-action="shop-order" data-id="${esc(o.id)}" style="text-align:left"><div><h3>${esc(o.items.map(l=>l.name).slice(0,3).join(', '))}${o.items.length>3?' …':''}</h3><p>${date(o.createdAt)} · ${time(o.createdAt)} · ${esc(o.id)}</p></div><div style="text-align:right"><b>${money(o.total)} so‘m</b><div style="margin-top:8px">${shopBadge(o.status)}</div></div></button>`).join('')}<h2 class="section-title">Taksi safarlari</h2>`:''}${list.map(o=>`<button class="card history-card full" data-action="order-detail" data-id="${o.id}" style="text-align:left"><div><h3>${esc(place(o.from))} → ${esc(place(o.to))}</h3><p>${date(o.createdAt)} · ${time(o.createdAt)} · ${esc(o.id)}</p></div><div style="text-align:right"><b>${money(o.price)} so‘m</b><div style="margin-top:8px">${badge(o.status)}</div></div></button>`).join('')||`<div class="card empty">${icon('car')}Hozircha safarlar yo‘q.<br><button class="btn lime space" data-page="home">Birinchi safarni boshlang</button></div>`}`;}
function profilePage(){return `<div class="consumer-hero"><div><div class="eyebrow">SHAXSIY KABINET</div><h1>Mening profilim</h1></div></div><div class="settings-grid"><div class="card pad"><div class="row"><div class="avatar" style="width:56px;height:56px;font-size:20px">${esc(initials(user.name))}</div><div><h2>${esc(user.name)}</h2><p class="hint">${esc(user.phone)}</p></div></div><div class="detail-list space"><div class="row"><small>Hisob turi</small><b>${user.role==='driver'?'Haydovchi':'Yo‘lovchi'}</b></div><div class="row"><small>Taksopark</small><b>${esc(state.settings.name)}</b></div><div class="row"><small>To‘lov usuli</small><b>Naqd pul</b></div></div><button class="btn outline full space" data-action="password">Parolni o‘zgartirish</button><button class="btn danger full space" data-action="logout">${icon('logout')} Hisobdan chiqish</button></div><div class="column"><div class="card pad"><h2>Yordam kerakmi?</h2><p class="hint">Savollaringiz bo‘lsa, park administratoriga murojaat qiling.</p><a href="tel:${esc(state.settings.phone.replace(/\s/g,''))}" class="btn lime full space">${icon('phone')} ${esc(state.settings.phone)}</a></div><div class="notice">${mode==='demo'?'Sinov versiyasi. Telefonlar, avtomobillar va safarlar namunaviy ma’lumotlardir.':'Hisobingiz serverga ulangan. Xarita hozircha demo yo‘nalishlar bilan ishlaydi.'}</div></div></div>`;}
function login(){return `<div class="login-shell"><div class="login-art">${logo()}<div><div class="eyebrow" style="color:#9aab8e">SHAHAR SIZ BILAN HARAKATDA</div><h1>Har safar.<br>Yangi <span>imkoniyat.</span></h1><p>Yo‘lovchi uchun qulaylik. Haydovchi uchun daromad. Parkingiz uchun to‘liq nazorat.</p></div><span class="tag">YO‘LOVCHI · HAYDOVCHI · TAKSOPARK</span></div><div class="login-form"><h2>Xush kelibsiz</h2><p>Hisobingizga kiring yoki sinov rejimida<br>platforma imkoniyatlarini ko‘ring.</p><div class="login-tabs"><button data-login-tab="login" class="${loginTab==='login'?'active':''}">Kirish</button><button data-login-tab="register" class="${loginTab==='register'?'active':''}">Ro‘yxatdan o‘tish</button></div><form data-form="login">${loginTab==='register'?'<label class="field">Ismingiz<input name="name" autocomplete="name" placeholder="Ism va familiya" required maxlength="80"></label>':''}<label class="field">Telefon raqamingiz<input name="phone" type="tel" autocomplete="tel" placeholder="+998 90 123 45 67" required></label><label class="field">Parol<input name="password" type="password" autocomplete="${loginTab==='login'?'current-password':'new-password'}" placeholder="Kamida 10 ta belgi" minlength="10" maxlength="128" required></label><div class="form-error" data-error role="alert"></div><button class="btn primary full">${loginTab==='login'?'Hisobga kirish':'Yo‘lovchi hisobini ochish'} ${icon('arrow')}</button></form><button class="text-link space" data-action="server">${icon('settings')} Server manzilini sozlash</button><div class="divider">SINOV REJIMIDA KO‘RISH</div><div class="demo-roles"><button data-role="rider">Yo‘lovchi</button><button data-role="driver">Haydovchi</button><button data-role="admin">Admin paneli</button></div><p class="hint">Demo ma’lumotlar shu qurilmada saqlanadi. Sinovda haqiqiy taksi chaqirilmaydi.</p><p class="version">NAVO TAXI · v0.1 · © 2026 Jovliyev Akobir</p></div></div>`;}
// ——— Do‘kon ———
const imgUrl=u=>u.startsWith('/images/')?apiBase+u:u;
function visual(p){return p.image?`<img src="${esc(imgUrl(p.image))}" alt="" loading="lazy">`:`<span class="emoji">${esc(p.emoji||'🛍️')}</span>`;}
function shopBadge(s){return `<span class="pill ${s==='delivered'?'green':s==='cancelled'?'red':s==='new'?'orange':'blue'}"><span class="dot"></span>${shopLabels[s]||esc(s)}</span>`;}
const cartCount=()=>Object.values(cart).reduce((a,q)=>a+q,0);
function cartLines(){return Object.entries(cart).map(([id,qty])=>({p:state.shop.products.find(p=>p.id===id),qty})).filter(l=>l.p);}
function stepper(id,qty){return `<div class="stepper"><button data-cart-sub="${esc(id)}" aria-label="Kamaytirish">${icon('minus')}</button><span>${qty}</span><button data-cart-add="${esc(id)}" aria-label="Ko‘paytirish">${icon('plus')}</button></div>`;}
function productCard(p){const qty=cart[p.id]||0,out=p.stock<=0;return `<div class="card product-card${out?' out':''}"><button class="product-img" data-action="product-detail" data-id="${esc(p.id)}" aria-label="${esc(p.name)}">${visual(p)}${out?'<span class="pill red stock-tag">Tugagan</span>':p.stock<=5?`<span class="pill orange stock-tag">${p.stock} ta qoldi</span>`:''}</button><div class="product-body"><h3>${esc(p.name)}</h3><small>${esc(p.unit)}</small><div class="product-foot"><b>${money(p.price)} <span>so‘m</span></b>${out?'':qty?stepper(p.id,qty):`<button class="add-btn" data-cart-add="${esc(p.id)}" aria-label="Savatga qo‘shish">${icon('plus')}</button>`}</div></div></div>`;}
function shopStatusCard(o){const steps=['new','packing','ready','delivering'],i=steps.indexOf(o.status),c=state.drivers.find(d=>d.id===o.courierId);return `<div class="status-card shop-status"><div class="row between"><span class="pill green">${esc(o.id)}</span>${shopBadge(o.status)}</div><h3>${({new:'Buyurtmangiz qabul qilindi',packing:'Buyurtmangiz yig‘ilmoqda',ready:'Kuryerga topshirilmoqda',delivering:'Kuryer yo‘lda'})[o.status]}</h3><div class="status-steps">${steps.map((_,k)=>`<span class="${k<=i?'done':''}"></span>`).join('')}</div><div class="row between"><small>${o.items.reduce((a,l)=>a+l.qty,0)} ta mahsulot · naqd</small><b>${money(o.total)} so‘m</b></div>${c?`<a href="tel:${esc(c.phone)}" class="btn outline full space">${icon('phone')} Kuryer: ${esc(c.name)}</a>`:''}<button class="text-link space" data-action="shop-order" data-id="${esc(o.id)}">Batafsil ${icon('arrow')}</button></div>`;}
function shopPage(){const sh=state.shop,st=sh.settings,q=shopQuery.trim().toLowerCase(),list=sh.products.filter(p=>(shopCat==='all'||p.categoryId===shopCat)&&(!q||`${p.name} ${p.desc}`.toLowerCase().includes(q)));const sub=cartLines().reduce((a,l)=>a+l.p.price*l.qty,0);return `<div class="consumer-hero"><div><div class="eyebrow">${esc(state.settings.city)} BO‘YLAB YETKAZIB BERISH</div><h1>Do‘kon</h1><p>${st.open?`Yetkazib berish: ${st.deliveryFee?money(st.deliveryFee)+' so‘m':'bepul'}${st.freeFrom&&st.deliveryFee?` · ${money(st.freeFrom)} so‘mdan bepul`:''}`:'Do‘kon hozir yopiq. Buyurtmalar vaqtincha qabul qilinmaydi.'}</p></div></div>${sh.orders.filter(o=>shopActive(o.status)).map(shopStatusCard).join('')}<label class="search shop-search">${icon('search')}<input data-shop-search placeholder="Mahsulot qidirish..." value="${esc(shopQuery)}" aria-label="Mahsulot qidirish"></label><div class="chips">${[{id:'all',name:'Barchasi',emoji:'🛒'},...sh.categories].map(c=>`<button data-cat="${esc(c.id)}" class="chip ${shopCat===c.id?'active':''}">${esc(c.emoji||'')} ${esc(c.name)}</button>`).join('')}</div><div class="product-grid">${list.map(productCard).join('')||'<div class="card empty">Mahsulot topilmadi.</div>'}</div>${cartCount()?`<button class="cart-bar" data-page="cart">${icon('cart')}<span>Savat · ${cartCount()} ta</span><b>${money(sub)} so‘m ${icon('arrow')}</b></button>`:''}`;}
function cartPage(){const st=state.shop.settings,lines=cartLines(),sub=lines.reduce((a,l)=>a+l.p.price*l.qty,0),del=lines.length&&!(st.freeFrom&&sub>=st.freeFrom)?st.deliveryFee:0,low=sub<st.minOrder,over=lines.some(l=>l.qty>l.p.stock);return `<div class="consumer-hero"><div><div class="eyebrow">SAVAT</div><h1>Savatingiz</h1><p>${cartCount()} ta mahsulot</p></div></div>${lines.length?`<div class="cart-layout"><div class="card pad">${lines.map(({p,qty})=>`<div class="cart-line"><div class="cart-thumb">${visual(p)}</div><div class="grow"><h3>${esc(p.name)}</h3><small>${esc(p.unit)} · ${money(p.price)} so‘m</small>${qty>p.stock?`<small class="warn">Omborda ${p.stock} ta qoldi</small>`:''}</div><div class="cart-side">${stepper(p.id,qty)}<b>${money(p.price*qty)} so‘m</b></div></div>`).join('')}</div><div class="card pad"><h2>Rasmiylashtirish</h2><div class="detail-list space"><div class="row"><small>Mahsulotlar</small><b>${money(sub)} so‘m</b></div><div class="row"><small>Yetkazib berish</small><b>${del?money(del)+' so‘m':'Bepul'}</b></div><div class="row total"><small>Jami</small><b>${money(sub+del)} so‘m</b></div></div>${st.freeFrom&&del&&sub<st.freeFrom?`<p class="hint">Yana ${money(st.freeFrom-sub)} so‘mlik xarid qilsangiz, yetkazish bepul.</p>`:''}<form data-form="checkout" class="space"><label class="field">Yetkazish manzili<input name="address" required maxlength="160" placeholder="Mahalla, ko‘cha, uy raqami" value="${esc(store.get('navo-address',''))}"></label><label class="field">Izoh (ixtiyoriy)<input name="comment" maxlength="200" placeholder="Masalan: darvoza yashil rangda"></label><div class="payment"><span class="row">${icon('wallet')} Naqd pul</span><span class="pill green">Kuryerga to‘lanadi</span></div><div class="form-error" data-error role="alert"></div><button class="btn primary full" ${!st.open||low||over?'disabled':''}>${!st.open?'Do‘kon hozir yopiq':over?'Savatdagi sonni kamaytiring':low?`Eng kam buyurtma: ${money(st.minOrder)} so‘m`:`Buyurtma berish · ${money(sub+del)} so‘m`}</button></form></div></div>`:`<div class="card empty">${icon('cart')}Savatingiz hozircha bo‘sh.<br><button class="btn lime space" data-page="shop">Xaridni boshlash</button></div>`}`;}
function productDetail(id){const p=state.shop.products.find(p=>p.id===id);if(!p)return;const cat=state.shop.categories.find(c=>c.id===p.categoryId);modal(esc(p.name),`<div class="product-photo large">${visual(p)}</div><div class="row between space"><div><small>${esc(cat?.name||'')} · ${esc(p.unit)}</small><h2 style="margin-top:6px">${money(p.price)} so‘m</h2></div>${p.stock<=0?'<span class="pill red">Tugagan</span>':`<span class="pill green">Omborda: ${p.stock}</span>`}</div>${p.desc?`<p class="hint">${esc(p.desc)}</p>`:''}${user.role==='rider'&&p.stock>0?`<button class="btn primary full space" data-cart-add="${esc(p.id)}" data-close="1">${icon('plus')} Savatga qo‘shish${cart[p.id]?` · savatda ${cart[p.id]} ta`:''}</button>`:''}`);}
function shopOrderDetail(id){const o=state.shop.orders.find(o=>o.id===id);if(!o)return;const c=state.drivers.find(d=>d.id===o.courierId),isAdmin=user.role==='admin',mine=user.role==='driver'&&o.courierId===user.driverId;const free=isAdmin?state.drivers.filter(d=>d.online&&!d.blocked&&!driverBusy(state,d.id)):[];modal('Buyurtma #'+esc(id),`<div class="detail-list"><div class="row"><small>Holat</small>${shopBadge(o.status)}</div><div class="row"><small>Mijoz</small><b>${esc(o.customer)}${o.phone?` · ${esc(o.phone)}`:''}</b></div><div class="row"><small>Manzil</small><b>${esc(o.address)}</b></div>${o.comment?`<div class="row"><small>Izoh</small><b>${esc(o.comment)}</b></div>`:''}<div class="row"><small>Kuryer</small><b>${esc(c?.name||'Biriktirilmagan')}</b></div></div><div class="order-items">${o.items.map(l=>`<div class="row between"><span>${esc(l.name)} <small>× ${l.qty} · ${esc(l.unit)}</small></span><b>${money(l.sum)}</b></div>`).join('')}<div class="row between"><small>Yetkazib berish</small><b>${o.delivery?money(o.delivery):'Bepul'}</b></div><div class="row between total"><span>Jami · naqd</span><b>${money(o.total)} so‘m</b></div></div>${isAdmin&&['new','packing'].includes(o.status)?`<button class="btn primary full space" data-action="shop-next" data-id="${esc(o.id)}" data-status="${shopNext[o.status]}">${o.status==='new'?'Qabul qilish va yig‘ishni boshlash':'Tayyor — kuryerga berish'}</button>`:''}${isAdmin&&o.status==='ready'?`<form data-form="shop-assign" class="space"><input type="hidden" name="id" value="${esc(o.id)}"><label class="field">Kuryerga biriktirish<select name="driverId" required><option value="">Kuryerni tanlang</option>${free.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(d.car)}</option>`).join('')}</select></label>${free.length?'':'<p class="hint">Bo‘sh onlayn kuryer yo‘q. Onlayn haydovchilar buyurtmani o‘zlari ham olishi mumkin.</p>'}<button class="btn primary full" ${free.length?'':'disabled'}>Biriktirish</button></form>`:''}${o.status==='delivering'&&(isAdmin||mine)?`<button class="btn primary full space" data-action="shop-next" data-id="${esc(o.id)}" data-status="delivered">Yetkazildi deb belgilash</button>`:''}${(isAdmin&&shopActive(o.status))||(user.role==='rider'&&o.status==='new')?`<button class="btn danger full space" data-action="shop-cancel" data-id="${esc(o.id)}">Buyurtmani bekor qilish</button>`:''}`);}
function deliveryCard(o,mine){return `<div class="card request-card"><div class="row between">${shopBadge(o.status)}<small>${esc(o.id)}</small></div><div class="request-route"><span><i class="dot"></i>Do‘kondan olish</span><span><i class="dot" style="background:#354f2c"></i>${esc(o.address)}</span></div><div class="row between" style="margin-bottom:20px;font-size:11px;color:#859377"><span>${o.items.reduce((a,l)=>a+l.qty,0)} ta mahsulot</span><span>Yetkazish: ${o.delivery?money(o.delivery)+' so‘m':'bepul'}</span></div>${mine?`<div class="row between" style="margin-bottom:20px"><span style="font-size:13px">${esc(o.customer)}</span><a href="tel:${esc(o.phone)}" class="text-link">${icon('phone')} Qo‘ng‘iroq</a></div>`:''}<div class="request-footer"><div><b>${money(o.total)}</b><small> so‘m naqd olinadi</small></div>${mine?`<button class="btn primary" data-action="shop-next" data-id="${esc(o.id)}" data-status="delivered">Yetkazildi ${icon('check')}</button>`:`<button class="btn lime" data-action="shop-accept" data-id="${esc(o.id)}">Olib ketaman ${icon('arrow')}</button>`}</div></div>`;}
function deliverySection(d,trip){const mine=state.shop.orders.find(o=>o.courierId===d.id&&shopActive(o.status)),ready=state.shop.orders.filter(o=>o.status==='ready');return `<div class="row between space" style="margin-bottom:18px"><h2>${mine?'Joriy yetkazib berish':'Yetkazib berish'}</h2><span class="pill">${mine?1:ready.length} ta</span></div><div class="requests-grid">${mine?deliveryCard(mine,true):!d.online?'<div class="card empty">Onlayn bo‘lsangiz, do‘kon buyurtmalari shu yerda ko‘rinadi.</div>':trip?'<div class="card empty">Avval joriy safarni yakunlang.</div>':ready.map(o=>deliveryCard(o,false)).join('')||'<div class="card empty">Yetkazishga tayyor buyurtma yo‘q.</div>'}</div>`;}
function shopAdmin(){const sh=state.shop,day=new Date();day.setHours(0,0,0,0);const todaySum=sh.orders.filter(o=>o.status==='delivered'&&o.deliveredAt>=day.getTime()).reduce((a,o)=>a+o.subtotal,0);const tabs=[['orders','Buyurtmalar'],['products','Mahsulotlar'],['categories','Kategoriyalar'],['settings','Sozlamalar']];return heading('Do‘kon','Mahsulotlar, buyurtmalar va yetkazib berish — bitta joyda.',`<button class="btn primary" data-action="product-edit">${icon('plus')} Mahsulot qo‘shish</button>`)+`<div class="stats">${[['Bugungi savdo',money(todaySum),'so‘m','Bugun yetkazilgan buyurtmalar'],['Faol buyurtmalar',sh.orders.filter(o=>shopActive(o.status)).length,'','Yangi, yig‘ilayotgan va yo‘lda'],['Mahsulotlar',sh.products.filter(p=>p.active).length,`/ ${sh.products.length}`,'Sotuvdagi mahsulotlar'],['Kam qolgan',sh.products.filter(p=>p.active&&p.stock<=5).length,'','Qoldig‘i 5 tadan kam']].map(([n,v,u,f],i)=>`<div class="stat ${i===0?'featured':''}"><span class="stat-label">${n}</span><div class="stat-value">${v} <span>${u}</span></div><div class="stat-foot">${f}</div></div>`).join('')}</div><div class="card"><div class="card-head"><div class="filters">${tabs.map(([t,n])=>`<button data-shop-tab="${t}" class="${shopTab===t?'active':''}">${n}</button>`).join('')}</div>${sh.settings.open?'<span class="pill green"><span class="dot"></span> Ochiq</span>':'<span class="pill red"><span class="dot"></span> Yopiq</span>'}</div>${({orders:shopOrdersTable,products:productsTable,categories:categoriesPanel,settings:shopSettingsPanel})[shopTab]()}</div>`;}
function shopOrdersTable(){return `<div class="table-wrap"><table class="table"><thead><tr><th>Buyurtma</th><th>Mijoz</th><th>Manzil</th><th>Kuryer</th><th>Summa</th><th>Holat</th><th></th></tr></thead><tbody>${state.shop.orders.map(o=>{const c=state.drivers.find(d=>d.id===o.courierId);return `<tr><td><b>#${esc(o.id)}</b><small>${date(o.createdAt)}, ${time(o.createdAt)}</small></td><td>${esc(o.customer)}<small>${esc(o.phone)}</small></td><td><div class="route-text">${esc(o.address)}<small>${o.items.reduce((a,l)=>a+l.qty,0)} ta mahsulot</small></div></td><td>${c?esc(c.name):'<span class="muted">—</span>'}</td><td><b>${money(o.total)}</b><small>so‘m · naqd</small></td><td>${shopBadge(o.status)}</td><td><button class="round" style="width:28px;height:28px" data-action="shop-order" data-id="${esc(o.id)}" aria-label="Buyurtmani ochish">${icon('chevron')}</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">Hali buyurtma yo‘q.</td></tr>'}</tbody></table></div>`;}
function productsTable(){const cat=id=>state.shop.categories.find(c=>c.id===id)?.name||'—';return `<div class="table-wrap"><table class="table"><thead><tr><th>Mahsulot</th><th>Kategoriya</th><th>Narx</th><th>Qoldiq</th><th>Holat</th><th></th></tr></thead><tbody>${state.shop.products.map(p=>`<tr><td><div class="row"><span class="cart-thumb small">${visual(p)}</span><div>${esc(p.name)}<small>${esc(p.unit)}</small></div></div></td><td>${esc(cat(p.categoryId))}</td><td><b>${money(p.price)}</b><small>so‘m</small></td><td>${p.stock<=0?'<span class="pill red">Tugagan</span>':p.stock<=5?`<span class="pill orange">${p.stock} ta</span>`:p.stock+' ta'}</td><td>${p.active?'<span class="pill green">Sotuvda</span>':'<span class="pill">Yashirin</span>'}</td><td><button class="round" style="width:28px;height:28px" data-action="product-edit" data-id="${esc(p.id)}" aria-label="Tahrirlash">${icon('edit')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Hali mahsulot yo‘q. «Mahsulot qo‘shish» tugmasini bosing.</td></tr>'}</tbody></table></div>`;}
function categoriesPanel(){const row=c=>`<form data-form="category" class="category-row"><input type="hidden" name="id" value="${esc(c.id||'')}"><input name="emoji" value="${esc(c.emoji||'')}" maxlength="8" placeholder="🛒" aria-label="Belgi" class="emoji-input"><input name="name" value="${esc(c.name||'')}" maxlength="40" required placeholder="Yangi kategoriya nomi" aria-label="Kategoriya nomi"><small>${c.id?state.shop.products.filter(p=>p.categoryId===c.id).length+' ta mahsulot':''}</small><button class="btn outline small">${c.id?'Saqlash':'Qo‘shish'}</button>${c.id?`<button type="button" class="btn danger small" data-action="category-delete" data-id="${esc(c.id)}">O‘chirish</button>`:''}</form>`;return `<div class="pad">${state.shop.categories.map(row).join('')}${row({})}</div>`;}
function shopSettingsPanel(){const st=state.shop.settings;return `<form data-form="shop-settings" class="pad shop-settings"><label class="check"><input type="checkbox" name="open" ${st.open?'checked':''}> Do‘kon ochiq — buyurtmalar qabul qilinadi</label><div class="two space"><label class="field">Yetkazib berish narxi (so‘m)<input name="deliveryFee" type="number" min="0" max="1000000" step="500" value="${st.deliveryFee}" required></label><label class="field">Bepul yetkazish chegarasi (so‘m)<input name="freeFrom" type="number" min="0" step="1000" value="${st.freeFrom}" required><small>Shu summadan oshsa yetkazish bepul. 0 — doim pullik.</small></label></div><label class="field space">Eng kam buyurtma (so‘m)<input name="minOrder" type="number" min="0" step="1000" value="${st.minOrder}" required></label><button class="btn primary space">${icon('check')} Saqlash</button></form>`;}
function productEdit(id){const p=state.shop.products.find(p=>p.id===id)||{active:true,unit:'1 dona',stock:0};if(!state.shop.categories.length){toast('Avval kategoriya qo‘shing.');shopTab='categories';render();return;}modal(id?'Mahsulotni tahrirlash':'Yangi mahsulot',`<form data-form="product"><input type="hidden" name="id" value="${esc(p.id||'')}"><div class="product-photo">${id?visual(p):'<span class="emoji">📷</span>'}</div><label class="field">Rasm (ixtiyoriy)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG yoki WEBP. Rasm avtomatik kichraytiriladi.</small></label><label class="field">Nomi<input name="name" value="${esc(p.name||'')}" required maxlength="80"></label><div class="two"><label class="field">Kategoriya<select name="categoryId" required>${state.shop.categories.map(c=>`<option value="${esc(c.id)}" ${p.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Belgi (emoji)<input name="emoji" value="${esc(p.emoji||'')}" maxlength="8" placeholder="🛍️"></label></div><div class="two"><label class="field">Narx (so‘m)<input name="price" type="number" min="100" step="100" value="${p.price??''}" required></label><label class="field">O‘lchov<input name="unit" value="${esc(p.unit||'')}" required maxlength="20" placeholder="1 kg, 1 dona"></label></div><div class="two"><label class="field">Qoldiq (soni)<input name="stock" type="number" min="0" step="1" value="${p.stock??0}" required></label><label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}> Sotuvda</label></div><label class="field">Tavsif<textarea name="desc" maxlength="300" rows="3">${esc(p.desc||'')}</textarea></label><div class="form-error" data-error></div><div class="modal-actions">${id?`<button type="button" class="btn danger" data-action="product-delete" data-id="${esc(id)}">O‘chirish</button>`:''}<button class="btn primary">Saqlash</button></div></form>`);}
async function shrink(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Rasm JPG, PNG yoki WEBP bo‘lsin.');if(file.size>15e6)throw Error('Rasm 15 MB dan katta.');const bmp=await createImageBitmap(file),k=Math.min(1,720/Math.max(bmp.width,bmp.height)),c=document.createElement('canvas');c.width=Math.round(bmp.width*k);c.height=Math.round(bmp.height*k);const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(bmp,0,0,c.width,c.height);return c.toDataURL('image/jpeg',0.8);}
function render(){document.title=(state?.settings.name||'NAVO TAXI')+' — Taksopark';$('#app').innerHTML=!user?login():user.role==='admin'?adminShell(({overview,orders:ordersPage,shop:shopAdmin,drivers:driversPage,finance:financePage,settings:settingsPage}[page]||overview)()):consumerShell(user.role==='rider'&&page==='shop'?shopPage():user.role==='rider'&&page==='cart'?cartPage():page==='history'?historyPage():page==='profile'?profilePage():user.role==='driver'?driverHome():riderHome());}
let previousFocus;
function modal(title,html){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button data-action="close-modal" aria-label="Yopish">×</button></div>${html}</section></div>`;setTimeout(()=>$('.modal input:not([type=hidden]),.modal select,.modal button')?.focus(),0);}
function closeModal(){$('#modal-root').innerHTML='';previousFocus?.focus();}
function driverEdit(id){const d=state.drivers.find(d=>d.id===id)||{};modal(id?'Haydovchini tahrirlash':'Yangi haydovchi',`<form data-form="driver"><input type="hidden" name="id" value="${esc(d.id||'')}"><label class="field">Ism va familiya<input name="name" value="${esc(d.name||'')}" required maxlength="80"></label><label class="field">Telefon<input name="phone" type="tel" value="${esc(d.phone||'+998')}" required></label><div class="two"><label class="field">Avtomobil<input name="car" value="${esc(d.car||'')}" placeholder="Chevrolet Cobalt" required maxlength="80"></label><label class="field">Davlat raqami<input name="plate" value="${esc(d.plate||'')}" placeholder="01 A 123 AA" required maxlength="20"></label></div>${mode!=='demo'?`<label class="field">${id?'Yangi parol (ixtiyoriy)':'Boshlang‘ich parol'}<input name="password" type="password" minlength="10" maxlength="128" ${id?'':'required'} autocomplete="new-password"><small>Kamida 10 ta belgi. Haydovchiga shaxsan yetkazing.</small></label>`:''}<div class="form-error" data-error></div><div class="modal-actions">${id?`<button type="button" class="btn danger" data-action="block-driver" data-id="${esc(id)}">${d.blocked?'Blokdan chiqarish':'Bloklash'}</button>`:''}<button class="btn primary">Saqlash</button></div></form>`);}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const d=state.drivers.find(d=>d.id===o.driverId);const available=state.drivers.filter(d=>d.online&&!d.blocked&&!state.orders.some(o=>o.driverId===d.id&&active(o.status)));modal('Buyurtma #'+esc(id),`<div class="detail-list"><div class="row"><small>Holat</small>${badge(o.status)}</div><div class="row"><small>Yo‘lovchi</small><b>${esc(o.rider)}</b></div><div class="row"><small>Qayerdan</small><b>${esc(place(o.from))}</b></div><div class="row"><small>Qayerga</small><b>${esc(place(o.to))}</b></div><div class="row"><small>Haydovchi</small><b>${esc(d?.name||'Biriktirilmagan')}</b></div><div class="row"><small>Narx · naqd</small><b>${money(o.price)} so‘m</b></div></div>${user.role==='admin'&&o.status==='pending'?`<form data-form="assign" class="space"><input type="hidden" name="id" value="${o.id}"><label class="field">Haydovchiga biriktirish<select name="driverId" required><option value="">Haydovchini tanlang</option>${available.map(d=>`<option value="${d.id}">${esc(d.name)} · ${esc(d.car)}</option>`).join('')}</select></label>${available.length?'':'<p class="hint">Bo‘sh onlayn haydovchi yo‘q.</p>'}<button class="btn primary full" ${!available.length?'disabled':''}>Biriktirish</button></form>`:''}${user.role==='admin'&&['accepted','arrived','riding'].includes(o.status)?`<button class="btn primary full space" data-action="advance" data-id="${o.id}" data-status="${({accepted:'arrived',arrived:'riding',riding:'completed'})[o.status]}">${({accepted:'Yetib kelgan deb belgilash',arrived:'Safarni boshlash',riding:'Safarni yakunlash'})[o.status]}</button>`:''}${(user.role==='admin'&&active(o.status))||(user.role==='rider'&&['pending','accepted'].includes(o.status))?`<button class="btn danger full space" data-action="cancel" data-id="${o.id}">Buyurtmani bekor qilish</button>`:''}`);}
function exportCSV(){if(window.location.hostname==='appassets.androidplatform.net'){toast('CSV hisobotini kompyuterdagi admin panelidan yuklang.');return;}const cols=['ID','Vaqt','Yo‘lovchi','Telefon','Qayerdan','Qayerga','Holat','Narx UZS','Komissiya UZS'];const safe=v=>`"${String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')}"`;const lines=[cols,...state.orders.map(o=>[o.id,new Date(o.createdAt).toISOString(),o.rider,o.phone,place(o.from),place(o.to),labels[o.status],o.price,o.status==='completed'?Math.round(o.price*o.commission/100):0])];const blob=new Blob(['\uFEFF'+lines.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='taksopark-hisobot.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Hisobot yuklandi.');}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button,[data-action]');if(!b||b.disabled)return;
 if(b.dataset.role){closeModal();setDemo(b.dataset.role);return;}
 if(b.dataset.cartAdd||b.dataset.cartSub){const id=b.dataset.cartAdd||b.dataset.cartSub,p=state.shop.products.find(p=>p.id===id);if(!p)return;const q=cart[id]||0;if(b.dataset.cartAdd){if(q>=Math.min(99,p.stock)){toast('Omborda boshqa qolmadi.');return;}cart[id]=q+1;}else if(q<=1)delete cart[id];else cart[id]=q-1;saveCart();if(b.dataset.close){closeModal();toast('Savatga qo‘shildi.');}render();return;}
 if(b.dataset.cat){shopCat=b.dataset.cat;render();return;}
 if(b.dataset.shopTab){shopTab=b.dataset.shopTab;render();return;}
 if(b.dataset.page){page=b.dataset.page;filter='all';search='';menu=false;render();window.scrollTo(0,0);return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.tariff){tariff=b.dataset.tariff;render();return;}
 if(b.dataset.loginTab){loginTab=b.dataset.loginTab;render();return;}
 const a=b.dataset.action,id=b.dataset.id;
 if(a==='close-modal'){closeModal();return;}
 if(a==='menu'){menu=!menu;render();return;}
 if(a==='logout'){if(mode!=='demo')try{await api('logout',{});}catch{}cart={};saveCart();token='';user=null;state=null;mode='';sessionStorage.removeItem('navo-mode');sessionStorage.removeItem('navo-token');render();return;}
 if(a==='book'){await act('order.create',{from,to,tariff},'Buyurtmangiz qabul qilindi.');return;}
 if(a==='cancel'){modal('Buyurtmani bekor qilish',`<p style="font-size:13px;line-height:1.7">${esc(id)} buyurtmasini bekor qilasizmi? Bu amalni qaytarib bo‘lmaydi.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Ortga</button><button class="btn danger" data-action="confirm-cancel" data-id="${esc(id)}">Bekor qilish</button></div>`);return;}
 if(a==='confirm-cancel'){if(await act('order.status',{id,status:'cancelled'},'Buyurtma bekor qilindi.'))closeModal();return;}
 if(a==='accept'){await act('order.assign',{id},'Buyurtmani qabul qildingiz.');return;}
 if(a==='advance'){if(await act('order.status',{id,status:b.dataset.status},b.dataset.status==='completed'?'Safar yakunlandi. Rahmat!':'Safar holati yangilandi.'))closeModal();return;}
 if(a==='online'){const d=state.drivers.find(d=>d.id===user.driverId);await act('driver.online',{online:!d.online},d.online?'Oflayn holatga o‘tdingiz.':'Siz onlaynsiz.');return;}
 if(a==='driver-edit'){driverEdit(id);return;}
 if(a==='block-driver'){if(await act('driver.block',{id},'Haydovchi holati o‘zgardi.'))closeModal();return;}
 if(a==='order-detail'){orderDetail(id);return;}
 if(a==='shop-order'){shopOrderDetail(id);return;}
 if(a==='product-detail'){productDetail(id);return;}
 if(a==='product-edit'){productEdit(id);return;}
 if(a==='product-delete'){modal('Mahsulotni o‘chirish',`<p style="font-size:13px;line-height:1.7">Mahsulot katalogdan butunlay o‘chiriladi. Vaqtincha yashirish uchun «Sotuvda» belgisini olib tashlang.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Ortga</button><button class="btn danger" data-action="product-delete-ok" data-id="${esc(id)}">O‘chirish</button></div>`);return;}
 if(a==='product-delete-ok'){if(await act('shop.product.delete',{id},'Mahsulot o‘chirildi.'))closeModal();return;}
 if(a==='category-delete'){await act('shop.category.delete',{id},'Kategoriya o‘chirildi.');return;}
 if(a==='shop-next'){if(await act('shop.status',{id,status:b.dataset.status},b.dataset.status==='delivered'?'Buyurtma yetkazildi. Rahmat!':'Buyurtma holati yangilandi.'))closeModal();return;}
 if(a==='shop-accept'){await act('shop.assign',{id},'Buyurtmani oldingiz. Mijozga yetkazing.');return;}
 if(a==='shop-cancel'){modal('Buyurtmani bekor qilish',`<p style="font-size:13px;line-height:1.7">${esc(id)} buyurtmasini bekor qilasizmi? Mahsulotlar omborga qaytariladi.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Ortga</button><button class="btn danger" data-action="shop-cancel-ok" data-id="${esc(id)}">Bekor qilish</button></div>`);return;}
 if(a==='shop-cancel-ok'){if(await act('shop.status',{id,status:'cancelled'},'Buyurtma bekor qilindi.'))closeModal();return;}
 if(a==='new-order'){modal('Yangi buyurtma',`<form data-form="order"><label class="field">Yo‘lovchi ismi<input name="rider" required maxlength="80" placeholder="Ism va familiya"></label><label class="field">Telefon<input name="phone" type="tel" required placeholder="+998 90 123 45 67"></label>${routeFields()}<label class="field">Tarif<select name="tariff">${state.tariffs.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><p class="notice">Demo manzillar. Narx serverdagi tariflar asosida taxminan hisoblanadi.</p><button class="btn primary full">Buyurtma yaratish</button></form>`);return;}
 if(a==='export'){exportCSV();return;}
 if(a==='support'){modal('Yordam markazi',`<p class="notice">${mode==='demo'?'Sinov rejimidagi telefon namunaviy. Haqiqiy raqamni admin panelidan kiriting.':'Park administratori bilan bog‘laning.'}</p><a class="btn primary full" href="tel:${esc(state.settings.phone.replace(/\s/g,''))}">${icon('phone')} ${esc(state.settings.phone)}</a>`);return;}
 if(a==='activity'){modal('Faollik jurnali',state.audit.slice(0,30).map(a=>`<div class="audit">${icon('clock')}<div>${esc(a.user)} · ${esc(({'order.create':'Buyurtma yaratildi','order.assign':'Haydovchi biriktirildi','order.status':'Safar holati yangilandi','settings.save':'Park sozlamalari o‘zgardi','tariff.save':'Tarif yangilandi','driver.save':'Haydovchi saqlandi','driver.block':'Haydovchi holati o‘zgardi','driver.online':'Onlayn holati yangilandi','shop.checkout':'Do‘kon buyurtmasi berildi','shop.assign':'Kuryer biriktirildi','shop.status':'Do‘kon buyurtmasi holati','shop.product.save':'Mahsulot saqlandi','shop.product.delete':'Mahsulot o‘chirildi','shop.category.save':'Kategoriya saqlandi','shop.category.delete':'Kategoriya o‘chirildi','shop.settings.save':'Do‘kon sozlamalari o‘zgardi'})[a.action]||a.action)}<small>${date(a.at)} ${time(a.at)} ${esc(a.detail)}</small></div></div>`).join('')||'<p class="empty">Hali yangi harakat yo‘q.</p>');return;}
 if(a==='server'){modal('Serverga ulanish',`<form data-form="server"><p class="notice">Hozir sinab ko‘rmoqchimisiz? Bu oynani yoping va pastdagi Yo‘lovchi, Haydovchi yoki Admin paneli tugmasini bosing. Bu maydon ishga tushirilgan HTTPS serveri bor administrator uchun.</p><label class="field">Server manzili<input name="url" type="url" value="${esc(apiBase)}" placeholder="Administrator bergan HTTPS manzili"><small>Oxirida /api yozmang. Kompyuterdagi panel o‘z serveriga avtomatik ulanadi.</small></label><div class="form-error" data-error></div><button class="btn primary full">Ulanishni tekshirish va saqlash</button><button type="button" class="btn outline full space" data-action="close-modal">Sinov rejimiga qaytish</button></form>`);return;}
 if(a==='password'){if(mode==='demo'){toast('Parolni serverga ulangan hisobda almashtirish mumkin.');return;}modal('Parolni almashtirish',`<form data-form="password"><label class="field">Amaldagi parol<input type="password" name="oldPassword" required autocomplete="current-password"></label><label class="field">Yangi parol<input type="password" name="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><div class="form-error" data-error></div><button class="btn primary full">Parolni saqlash</button></form>`);}
});
document.addEventListener('change',e=>{if(e.target.dataset.route&&!e.target.closest('.modal')){if(e.target.dataset.route==='from')from=e.target.value;else to=e.target.value;render();}});
document.addEventListener('input',e=>{for(const [attr,set] of [['data-search',v=>search=v],['data-shop-search',v=>shopQuery=v]])if(e.target.hasAttribute(attr)){const start=e.target.selectionStart;set(e.target.value);render();const input=$(`[${attr}]`);input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.dataset.form)return;e.preventDefault();const p=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;const error=form.querySelector('[data-error]');if(error)error.textContent='';
 try{
   const f=form.dataset.form;
   if(f==='login'){const r=await api(loginTab,p);cart={};saveCart();user=r.user;state=r.state;token=r.token;mode='live';page=user.role==='admin'?'overview':'home';sessionStorage.setItem('navo-token',token);sessionStorage.setItem('navo-mode','live');render();toast('Xush kelibsiz!');}
   else if(f==='settings')await act('settings.save',p,'Park ma’lumotlari yangilandi.');
   else if(f==='tariff')await act('tariff.save',p,'Tarif yangilandi.');
   else if(f==='driver'){if(await act('driver.save',p,'Haydovchi saqlandi.'))closeModal();}
   else if(f==='order'){if(await act('order.create',p,'Yangi buyurtma yaratildi.'))closeModal();}
   else if(f==='assign'){if(await act('order.assign',p,'Haydovchi biriktirildi.'))closeModal();}
   else if(f==='password'){await api('password',p);closeModal();toast('Parol yangilandi.');}
   else if(f==='checkout'){const items=Object.entries(cart).map(([id,qty])=>({id,qty}));store.set('navo-address',p.address);if(await act('shop.checkout',{items,address:p.address,comment:p.comment},'Buyurtmangiz qabul qilindi!')){cart={};saveCart();page='shop';render();window.scrollTo(0,0);}}
   else if(f==='product'){delete p.photo;const file=form.querySelector('input[type=file]')?.files[0];if(file){const data=await shrink(file);p.image=mode==='demo'?data:(await api('image',{data})).url;}if(await act('shop.product.save',p,'Mahsulot saqlandi.'))closeModal();}
   else if(f==='category')await act('shop.category.save',p,'Kategoriya saqlandi.');
   else if(f==='shop-settings')await act('shop.settings.save',p,'Do‘kon sozlamalari saqlandi.');
   else if(f==='shop-assign'){if(await act('shop.assign',p,'Kuryer biriktirildi.'))closeModal();}
   else if(f==='server'){
     let url=p.url.trim().replace(/\/+$/,'');if(url){const u=new URL(url);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Server uchun HTTPS manzili kerak.');if(u.username||u.password||u.search||u.hash)throw Error('Oddiy server manzilini kiriting.');}
     const old=apiBase;apiBase=url;try{await api('health');}catch(err){apiBase=old;throw err;}localStorage.setItem('navo-server',url);closeModal();toast('Server ulandi. Endi hisobingizga kiring.');
   }
 }catch(err){const msg=err.name==='TimeoutError'?'Server javob bermadi. Ulanishni tekshiring.':err.message==='Failed to fetch'?'Serverga ulanmadi. Serverni ishga tushiring yoki sinov rejimini tanlang.':err.message;if(error)error.textContent=msg;else toast(msg);}finally{if(button)button.disabled=false;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button:not(:disabled),input:not([type=hidden]),select,a[href]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('storage',e=>{if(e.key==='navo-demo-v1'&&mode==='demo'){loadDemo();render();}});
let pollError=false;
setInterval(async()=>{if(!user||mode!=='live'||busy||document.hidden)return;try{const r=await api('state');if(JSON.stringify(r.state)!==JSON.stringify(state)&&!$('#modal-root').children.length&&!document.activeElement?.matches('input,select')){state=r.state;user=r.user;render();}pollError=false;}catch(e){if(!pollError)toast('Server bilan aloqa uzildi. Ma’lumotlar yangilanmayapti.');pollError=true;}},5000);
async function init(){const demo=new URLSearchParams(location.search).get('demo');if(demo&&demoUsers[demo]){setDemo(demo);return;}if(mode==='demo'){setDemo(sessionStorage.getItem('navo-role')||'rider');return;}if(token){$('#app').innerHTML='<div class="loading">Parkingiz yuklanmoqda…</div>';try{const r=await api('state');user=r.user;state=r.state;page=user.role==='admin'?'overview':'home';}catch{token='';mode='';sessionStorage.removeItem('navo-token');}}render();}
init();
